class FlabCrusher extends AudioWorkletProcessor {
  constructor(o) {
    super();
    this.p = Object.assign({ bits: 8, downsample: 4, mix: 1 }, (o.processorOptions || {}).params);
    this.port.onmessage = (e) => Object.assign(this.p, e.data);
    this.held = [0, 0];
    this.count = 0;
  }
  process(inputs, outputs) {
    const inp = inputs[0], out = outputs[0];
    const step = Math.pow(2, 1 - Math.max(1, Math.min(16, this.p.bits)));
    const ds = Math.max(1, Math.round(this.p.downsample));
    const mix = this.p.mix;
    for (let c = 0; c < out.length; c++) {
      const x = inp[c] || inp[0];
      const y = out[c];
      if (!x) { y.fill(0); continue; }
      let count = this.count;
      for (let i = 0; i < y.length; i++) {
        if (count++ % ds === 0) this.held[c] = Math.round(x[i] / step) * step;
        y[i] = x[i] + (this.held[c] - x[i]) * mix;
      }
      if (c === out.length - 1) this.count = count;
    }
    return true;
  }
}
registerProcessor("flab-crusher", FlabCrusher);
